def _build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head

def _to_list(node):
    out = []
    while node is not None and len(out) < 10000:
        out.append(node.val)
        node = node.next
    return out

def test_basic():
    assert _to_list(merge_sorted_lists(_build([1, 4, 6]), _build([2, 4, 9]))) == [1, 2, 4, 4, 6, 9]

def test_one_empty():
    assert _to_list(merge_sorted_lists(None, _build([0, 3]))) == [0, 3]
    assert _to_list(merge_sorted_lists(_build([5]), None)) == [5]

def test_both_empty():
    assert merge_sorted_lists(None, None) is None
    assert _to_list(merge_sorted_lists(_build([]), _build([1]))) == [1]

def test_disjoint_ranges():
    assert _to_list(merge_sorted_lists(_build([10, 11]), _build([1, 2, 3]))) == [1, 2, 3, 10, 11]

def test_negatives_and_duplicates():
    assert _to_list(merge_sorted_lists(_build([-3, -3, 0]), _build([-3, 1]))) == [-3, -3, -3, 0, 1]
